package com.example.bandlink.service; import com.example.bandlink.entity.*; import com.example.bandlink.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminUserService {private final UserRepository users;private final PostRepository posts;private final AccountDeletionService accountDeletion;public AdminUserService(UserRepository u,PostRepository p,AccountDeletionService accountDeletion){users=u;posts=p;this.accountDeletion=accountDeletion;}@Transactional public void suspend(Long id){User u=change(id,UserStatus.SUSPENDED);posts.findByUserIdAndStatus(id,PostStatus.OPEN).forEach(p->p.close(ClosedReason.SUSPENDED,java.time.LocalDateTime.now()));}@Transactional public void unsuspend(Long id){change(id,UserStatus.ACTIVE);}
    // Suspend only closes posts (an operator may reinstate the account). This is the operator-initiated
    // counterpart to the self-service withdraw - a full, irreversible removal of the account and
    // everything it owns, including posts - for accounts an operator decides must be gone entirely.
    @Transactional public void delete(Long id){users.findById(id).orElseThrow();accountDeletion.deleteUserData(id);}
    private User change(Long id,UserStatus s){User u=users.findById(id).orElseThrow();if(u.getStatus()!=UserStatus.WITHDRAWN)u.setStatus(s);return u;}}
